typedef unsigned char u_char;
typedef unsigned int u_int;

enum
{
  NGLINT_FINISH,
  NGLINT_LOADTEXTURE,
};

struct nglVif1IntEntry
{
  u_int Type;
  u_int* GifDMA;
  u_int DataSize;
  u_int NTextures;
};

struct nglDebugStruct
{
  u_char ShowPerfInfo;
  u_char ScreenShot;
  u_char DisableQuads;
  u_char DisableMeshes;
  u_char DisableTextures;
  u_char DisableMipmaps;
  u_char DisableVSync;
  u_char DisableScratch;
  u_char DisableMipOpt;
  u_char DebugPrints;
  u_char DumpFrameLog;
  u_char DumpSceneFile;
  u_char DumpTextures;
  u_char DrawLightSpheres;
  u_char DrawMeshSpheres;
  u_char DrawNormals;
  u_char DrawAsPoints;
  u_char DrawAsLines;
  u_char VUClearMem;
  u_char VUClearRegs;
  u_char VUDebugBreak;
  u_char VUParticleDebugBreak;
  u_char DMARepeatMode;
  u_char DrawToFrontBuffer;
  u_char SyncRender;
};

struct nglPerfInfoStruct
{
  float FPS;
  u_int RenderStart;
  u_int RenderFinish;
};

extern nglDebugStruct nglSyncDebug;
extern nglPerfInfoStruct nglPerfInfo;
extern int _nglNVif1IntEntries;
extern int _nglVif1IntEntryIdx;
extern nglVif1IntEntry* _nglVif1IntArray;
extern volatile bool nglDMAFinished;

extern void nglGifSafeWait();
extern void nglPrintf( const char* Format, ... );
extern void nglWarning( const char* Format, ... );
extern void ExitHandler();

inline long volatile nglGetCPUCycle()
{
  register unsigned long result;
  __asm__ volatile ("mfc0 %0,$9" : "=r" (result));
  return result;
}

static inline void sync_l()
{
  __asm__ ("
    .set noreorder
    sync.l
    nop
    .set reorder
  ");
}

#define START_PROF_TIMER(x)
#define STOP_PROF_TIMER(x)
#define DEBUG_ENABLE(x) ( nglSyncDebug.x )
#define INTC_VIF1 5
#define T1_COUNT ((volatile u_int*)0x10000800)
#define D_STAT ((volatile u_int*)0x1000e010)
#define D2_CHCR ((volatile u_int*)0x1000a000)
#define D2_MADR ((volatile u_int*)0x1000a010)
#define D2_QWC ((volatile u_int*)0x1000a020)
#define D2_TADR ((volatile u_int*)0x1000a030)
#define NGL_DMA_MEM 0x0FFFFFFF
#define _nglDmaStartGifSourceChain(addr, tte)                         \
  {                                                                  \
    sync_l();                                                        \
    *D_STAT  = 1 << 2;                                               \
    *D2_QWC  = 0x00;                                                 \
    *D2_MADR = 0x00;                                                 \
    *D2_TADR = (u_int)(addr) & NGL_DMA_MEM;                           \
    *D2_CHCR = 1 | (1<<2) | (0<<4) | (tte<<6) | (0<<7) | (1<<8);     \
    sync_l();                                                        \
  }
#define VIF1_FBRST_STC_M 0x8
#define DPUT_VIF1_FBRST(x) (*(volatile u_int*)0x10003c10 = (x))

int nglVif1Interrupt( int ca )
{
  START_PROF_TIMER( proftimer_send_interrupt );

  // This shouldn't be neccessary, if FLUSHA in the VIF chain takes care of it (but it doesn't).
  START_PROF_TIMER( proftimer_send_interrupt_dmawait );
  nglGifSafeWait();
  STOP_PROF_TIMER( proftimer_send_interrupt_dmawait );

  register int cnt;
  if ( DEBUG_ENABLE( DebugPrints ) )
  {
    cnt = *T1_COUNT;
    nglPrintf( "enter interrupt %d at %d cycles.\n", _nglVif1IntEntryIdx, cnt );
  }

  if ( ca != INTC_VIF1 )
  {
    nglWarning( "nglVif1Interrupt: Bad interrupt cause.\n" );
    goto InterruptExit;
  }

  if ( _nglVif1IntEntryIdx >= _nglNVif1IntEntries )
  {
    nglWarning( "nglVif1Interrupt: Extra interrupt received (%d/%d).\n", _nglVif1IntEntryIdx + 1, _nglNVif1IntEntries );
    goto InterruptExit;
  }

  nglVif1IntEntry* Entry;
  Entry = &_nglVif1IntArray[_nglVif1IntEntryIdx++];
  if ( Entry->Type == NGLINT_FINISH )
  {
    nglPerfInfo.RenderFinish = nglGetCPUCycle();
    nglDMAFinished = true;
  }
  else
  if ( Entry->Type == NGLINT_LOADTEXTURE )
  {
    // Start a path 3 (dma channel 2) chain mode transfer
    if ( Entry->NTextures )
      _nglDmaStartGifSourceChain( Entry->GifDMA, 0 );
  }

InterruptExit:
  if ( DEBUG_ENABLE( DebugPrints ) )
  {
    cnt = *T1_COUNT;
    nglPrintf( "leave interrupt %d at %d cycles.\n", _nglVif1IntEntryIdx - 1, cnt );
  }

  // Restart the VIF.
  DPUT_VIF1_FBRST( VIF1_FBRST_STC_M );
  asm __volatile__(" sync.l ");

  STOP_PROF_TIMER( proftimer_send_interrupt );

  // to insure all store instructions are complete
  ExitHandler();
  return 0;
}
